def make(slug, title, category, pages, lead, sections, timeline, related, topics, sources, position):
    return {
        "slug": slug,
        "title": title,
        "short_title": title.split(" ── ")[0],
        "category": category,
        "book_pages": pages,
        "lead": lead,
        "description": lead,
        "sections": sections,
        "timeline": timeline,
        "related": related,
        "topics": topics,
        "official_sources": sources,
        "position": position,
    }


ARTICLES = [
make("c155", "中部第129部隊 ── 磐田原に置かれた電波警戒部隊を検証する", "磐田共通・戦争遺跡史", "94〜95", "磐田原に置かれた中部第129部隊は、磐田市の最新の平和資料が「第一航空情報連隊」「日本で最初の電波警戒機部隊」と説明する。部隊の存在、土地利用、出動、戦後の記憶を分け、地域の誇りにも恐怖の物語にも寄せず検証する。", [
("部隊名をまず固定する", ["地域資料は昭和17年（1942年）に磐田原台地へ陸軍の部隊が置かれ、通称を中部第129部隊と記す。磐田市の平和資料は正式名称を第一航空情報連隊とし、国土防空を目的とした電波警戒機部隊だったと説明する。", "古い記事や回想には第一航空軍情報連隊など表記揺れがある。正式名称、秘匿名、通称、後年の呼称を一つにせず、本稿は市の現行説明を基準にして、異表記は照合課題として残す。", "部隊番号だけでは任務は分からない。飛行場部隊、飛行学校、航空情報部隊は別組織であり、<a href=\"/oishi-ronko/235/\">天竜分教所跡</a>と混同しないことが出発点になる。"]),
("電波警戒という任務", ["磐田市資料は同部隊を日本で最初の電波警戒機部隊とする。電波で航空機を探知し、敵機接近を防空組織へ伝える任務は、航空機を運用する飛行場とは異なる。装置、通信、観測、指揮を支える多数の要員が必要だった。", "ただし『日本初』は何を単位にするかで意味が変わる。装置の試験、部隊の編成、実戦配備のいずれを指すかを確認しないまま技術史上の最初と断定しない。本稿は市資料の表現として紹介する。", "技術の先進性だけを称えると、探知情報が戦争遂行に使われ、多くの将兵が各戦域へ送られた事実が薄れる。反対に秘密兵器という語だけで誇張すると、通信と訓練の地道な実務が見えなくなる。"]),
("磐田原の土地が選ばれた理由", ["台地は低地より見通しがよく、大規模施設を置ける土地があったと考えられる。しかし資料が選地理由を明記していないため、地形からの理解は推定にとどめる。交通、電力、通信線、用地取得も同時に検討すべきである。", "地域資料は戦時中に約4千人が駐留し、特別訓練を受けた者が延べ2万人名に及ぶとする。常時人数と累計訓練者を同じ規模として足さない。調査時点と集計範囲が未確認であるため概数として扱う。", "軍用地化は所有者、耕作者、周辺住民に別々の影響を与えた。買収・借上げ・接収の法的形態、補償額、移転の有無は土地台帳と公文書を見なければ確定できない。"]),
("全国の戦域へ出た人びと", ["磐田市の平和資料は、ここで育成された将兵が太平洋戦争の全戦域へ出動し、多くが帰還しなかったと記す。これは部隊を磐田だけの施設史に閉じず、前線と地域を結ぶ重要な指摘である。", "一方、戦没者数、派遣先、時期を示す名簿は本稿の資料だけではそろわない。『多く』を具体数に置き換えず、軍歴資料、留守名簿、戦没者名簿、遺族資料で確認する。", "個人名を公開する場合は、階級や戦歴を一枚の名簿から断定しない。同姓同名、転属、原隊と派遣隊の違いがあるため、複数資料の一致と遺族への配慮が必要になる。"]),
("戦後の跡地と記憶", ["終戦後、軍用地は教育・公園・住宅・農地など別用途へ転換された可能性がある。<a href=\"/c083.html\">兜塚古墳</a>周辺には軍事利用の記憶もあるが、部隊区域と現在の施設境界を重ねるには旧版地図と払い下げ記録が要る。", "塹壕や基礎、通信施設の痕跡が見つかっても、形だけで用途を決めない。年代測定、配置図、建築材料、同時代写真を合わせ、戦後造成による構造物と区別する。", "戦争遺跡を保存する意味は兵器の珍しさではない。土地の接収、訓練、出征、空襲不安、終戦後の転用という複数の経験を、一つの場所から問い直せる点にある。"]),
("史料をどう組み合わせるか", ["部隊史は軍側資料だけでは住民の経験が薄く、回想だけでは編制と年月が揺れる。陸軍公文書、磐田市資料、新聞、地籍図、航空写真、聞き取りを相互に照合する。", "軍事機密のため同時代記録が意図的に曖昧な場合もある。戦後の回想が沈黙を埋める一方、数十年後の記憶には他施設との混同が生じ得る。両方の限界を明記する。", "現時点で確実なのは、市が1942年の開隊、第一航空情報連隊、中部129部隊、電波警戒任務を公式資料で示す点である。施設配置と全訓練者数の内訳は今後の確認課題である。"]),
("地域展示で避けること", ["『日本初』を観光的な呼び文句だけにせず、その根拠資料と定義を併記する。装置の技術説明と、戦争が地域・植民地・前線にもたらした被害を同じ展示空間で扱う必要がある。", "部隊経験者を英雄か加害者の一語で括らない。徴集、志願、配置、任務、年齢は一人ずつ異なる。個人の内面を推測せず、制度と確認できる行動を記録する。", "跡地を訪ねる際は私有地へ入らず、地表の物を動かさない。位置情報の公開も文化財保護と所有者の生活を優先し、公道から確認できる範囲に限る。"])], [("1942", "磐田原台地に第一航空情報連隊が開隊。"), ("1942〜1945", "電波警戒要員を訓練し各戦域へ派遣。"), ("1945-08", "敗戦により部隊解体と施設転用が始まる。")], [("h001.html", "戦争体験特集"), ("c083.html", "兜塚古墳と軍事利用"), ("oishi-ronko/235/", "天竜分教所跡"), ("u043.html", "田原の地震と戦争")], ["中部第129部隊", "第一航空情報連隊", "電波警戒", "磐田原", "戦争遺跡"], [OFFICIAL_IWATA_PEACE], "市の現行資料で確認できる名称と任務を史実とし、選地理由や施設配置は推定・未確認として分けた。戦後の記憶を軍事技術の賛美へ回収しない。"),

make("c156", "占領軍と地方軍政部 ── 敗戦後の磐田行政はどう監督されたか", "磐田共通・占領期行政史", "102〜107", "終戦後の磐田では占領軍の進駐と地方軍政部の行政視察が別の局面として現れた。ジープを見た住民の記憶と、学校・役所へ届いた命令を分け、占領が地域行政の日常へ入った経路を検証する。", [
("進駐軍と軍政部は同じではない", ["地域資料は昭和20年9月に連合軍が新所原へ到着し、磐田地方にもジープで連絡に来たと記す。これは部隊の移動・駐留の記憶であり、県や市町村を監督した軍政部の行政活動とは区別する。", "占領軍という総称の下には、軍事部隊、GHQ/SCAP、地方軍政部、後の民事部がある。命令の発信主体を確かめず、すべて『GHQが直接命じた』とは書かない。", "アジア歴史資料センターの公文書は、1948年7月に軍政局を民事局、地方軍政部を地方民事部へ改称した経過を示す。名称変更は占領終了ではなく、監督方式の変化として読む。"]),
("最初の接触をどう読むか", ["資料には白旗を掲げた役場関係者が見付附属署へ出向いた記述がある。地域側が無用な衝突を避け、命令経路を確保しようとした場面として読めるが、代表者の氏名と正確な日時は追加確認が必要である。", "住民が見たジープ、軍服、英語は占領の可視的記憶になった。しかし占領政策の多くは、県庁や教育委員会を通じた文書、報告、統計、検閲として届いた。見える兵士だけで占領を説明しない。", "恐怖、好奇心、解放感、反発は人によって異なる。後年の回想を地域全体の感情へ一般化せず、話者の年齢、立場、語られた時点を添える。"]),
("行政視察で見られたもの", ["地域資料は昭和21年11月、静岡軍政部の行政担当者が磐田高等女学校などを視察したと記す。学校、役所、警察の運営が民主化・非軍事化の観点から確認された時期だった。", "視察があったことと、その場で具体的な命令が出たことは別である。視察報告、学校日誌、県からの通達が一致して初めて、変更の因果関係を確定できる。", "学校では教科書の墨塗り、国旗・御真影の扱い、教員の適格審査、男女共学化など複数の改革が重なった。各改革を一回の視察の結果へまとめない。"]),
("文書命令が地域へ届くまで", ["占領政策はGHQから中央政府、県、市町村、学校・警察という経路で翻訳・通知された。英語原文、日本政府の指令、県通達、現場の実施記録を並べると、中央命令と地域運用の差が見える。", "同じ用語でも訳語が揺れ、軍政部の助言が命令として受け止められた例も考えられる。文書の発信番号、宛先、受領印、施行日を確認し、口頭指示との区別をつける。", "<a href=\"/c153.html\">PTAの成立</a>や<a href=\"/c104.html\">学校の男女共学化</a>は占領期改革と関係するが、地域側の準備や選択もあった。外圧だけ、自発性だけの一方で説明しない。"]),
("民主化と統制の両面", ["地方自治、教育、労働、農地改革などは民主化を掲げて進められた。一方で検閲、報告義務、占領当局の監督があり、主権が制限された時期でもある。二つは同時に存在した。", "改革の理念が住民の権利を広げたとしても、すべてが地域の合意で進んだとは限らない。逆に占領下だからという理由だけで、女性参政権や労働権の拡大を無意味とみなすこともできない。", "行政史では政策の評価と実施過程を分ける。誰が提案し、誰が決裁し、誰が費用を負担し、住民がどう利用したかを個別に追う。"]),
("兵士との交流を史料化する", ["物々交換、写真、菓子、英語会話などの記憶が残っていても、占領軍全体の政策と同じではない。個人接触は生活史として位置づけ、相手部隊、場所、年月を確かめる。", "写真は制服や車両番号から手掛かりを得られるが、撮影場所の誤認が起きやすい。建物、道路、山並みを旧版地図と照合し、肖像の公開には権利と尊厳へ配慮する。", "米兵を一様な存在とせず、軍政担当、輸送部隊、警備、通訳など役割を分ける。日本側も役場、警察、学校、商店、子どもで経験が異なる。"]),
("確認できる範囲", ["確実なのは、地域資料が終戦直後の連合軍接触と1946年の軍政部視察を記すこと、公文書が軍政部から民事部への改称を示すことである。", "未確認なのは、磐田に常駐した部隊の有無、最初のジープ来訪日、視察官氏名、個別命令の全文である。『進駐軍が磐田を占領した』という大づかみな言い方を避ける。", "今後は市・県公文書、学校日誌、警察沿革、占領軍側報告を突合する。地域の回想は問いを作る一次資料として尊重し、行政上の事実認定は公文書で補う。"])], [("1945-08-15", "敗戦。占領開始へ移る。"), ("1945-09", "連合軍が静岡県西部へ進出。"), ("1946-11", "静岡軍政部関係者が地域を視察したと資料が記す。"), ("1948-07", "軍政部が民事部へ改称。")], [("h008.html", "終戦の日"), ("c153.html", "PTAの成立"), ("c104.html", "戦後の磐田南高校"), ("c161.html", "農地改革")], ["占領軍", "地方軍政部", "地方民事部", "行政視察", "戦後改革"], [OFFICIAL_ARCHIVES, OFFICIAL_IWATA_PEACE], "地域資料の回想と占領側公文書を別の史料系列として扱い、進駐、軍政、民政移管を同じ出来事にしない。個別命令が確認できない改革は因果を断定しない。"),

make("c157", "引揚者住宅 ── 外地から戻った人びとの生活再建", "磐田共通・戦後生活史", "106", "戦後、外地から磐田地方へ戻った引揚者は、住まい、仕事、戸籍、就学を同時に立て直した。地域資料の『引揚者住宅』を入口に、全国の援護制度と地域の受け入れを照合し、帰還を一日の出来事で終わらせない。", [
("引揚げとは何か", ["引揚げは、敗戦によって日本の統治地域や戦地にいた軍人・一般邦人が日本へ戻る過程を指す。復員と一般邦人の帰還は手続きが異なり、上陸地から郷里へ着けば問題が終わったわけではない。", "厚生白書は、帰還手当、証明書、輸送、車中援護、定着先での住宅・就職支援を列挙する。引揚げを船の到着だけでなく、生活基盤を再構築する行政過程として捉える必要がある。", "地域資料が使う『外地』は当時の行政語であり、植民地支配の歴史を含む。現在の地名と政治的背景を注記し、失った日本人生活だけを語って現地住民の被害を消さない。"]),
("磐田地方の規模", ["地域資料は磐田地方の引揚者が相当数に達し、自治体が住宅対応を迫られたと記す。だが郡・町・市の範囲、集計日、世帯数と人数が明示されない箇所は概数として扱う。", "帰還先は本籍地、親族宅、縁故地、割当住宅など複数ある。磐田で受け付けた人数と、その後定住した人数は一致しない。転出入と世帯分離を含む台帳が必要になる。", "満州、朝鮮、樺太、台湾、南洋など出発地域により時期と経路が異なった。『引揚者』を同じ経験の集団にせず、地域・年月・家族構成を分ける。"]),
("住宅はなぜ足りなかったか", ["空襲被害、資材不足、復員者の増加、世帯形成が重なり、戦後の住宅不足は引揚者だけの問題ではなかった。親族宅への同居や寺社・公共施設の一時利用も想定される。", "厚生白書は1946〜1950年度に国所管の引揚者住宅が全国で1万9308戸に達したとする。この全国値を磐田の供給戸数と混同せず、地方の記録を比較する基準として用いる。", "応急住宅は老朽化や借上げ期限という二次問題を生んだ。入居できたことを支援の完了とせず、上下水道、通学、仕事場、家賃、修繕まで追う。"]),
("住宅選定と公平", ["誰を優先入居させるかは、世帯人数、傷病、遺族、収入、親族支援の有無などを基準にした可能性がある。実際の磐田基準は申請書と選考会記録で確認する。", "引揚者専用住宅は支援になる一方、周囲から区別される印にもなり得た。差別や対立を想定で書かず、聞き取り、自治会記録、学校記録から具体的に確かめる。", "公有地、旧軍用地、借地のどこに建てたかで戦後土地政策との関係が変わる。位置を公開する際は現住者のプライバシーを優先する。"]),
("仕事と住まいの結び付き", ["定着には仕事が必要だった。農地開拓、工場、商業、日雇い、公務など選択肢は経歴と地域需要で異なり、職業紹介は住宅政策と切り離せない。", "外地での資格や職歴が内地でそのまま認められない場合もあった。教師、技術者、商人、農業者の再就職を一括せず、資格証明と求人記録を調べる。", "<a href=\"/c164.html\">職業紹介の歴史</a>と合わせると、住民登録、食糧配給、住居、就職が一連の行政窓口だったことが分かる。"]),
("子どもと学校", ["引揚児童は転入時期、学年判定、教科書、衣服、言語、健康の問題を抱え得た。学校日誌は人数を記すが、個々の体験は作文や聞き取りで補う。", "海外生活を理由とするいじめや好奇の視線があったという全国的証言は、磐田での実態を自動的に証明しない。地域証言を得た場合も話者の匿名性を守る。", "教育支援を慈善だけで説明せず、就学権と行政責任の観点から読む。PTAや婦人会の衣料支援があれば、公費支援との役割分担を確認する。"]),
("数字を再検証する", ["引揚者数は入港統計、県受付、自治体転入、住宅入居で母数が異なる。同じ『人数』でも通過者、定着者、世帯員を分け、集計日を添える。", "住宅戸数も新築、転用、借上げ、補修を分ける。厚生白書の全国値と町村決算の戸数を単純比較せず、所管と年度をそろえる。", "現時点では磐田の住宅所在地と戸数を確定できない。地域資料が課題を記した事実と全国制度は確認できるが、個別配置は未確認として公開する。"])], [("1945", "敗戦後、軍人・一般邦人の引揚げが本格化。"), ("1946", "引揚援護院設置。"), ("1946〜1950", "全国で引揚者住宅の新設・転用が進む。"), ("1950年代", "老朽住宅の更新と定着援護が課題になる。")], [("c158.html", "満蒙開拓と磐田"), ("c164.html", "職業紹介と雇用"), ("h004.html", "銃後の生活"), ("c156.html", "占領軍と軍政部")], ["引揚者", "引揚者住宅", "復員", "定着援護", "戦後生活"], [OFFICIAL_MHLW_REPATRIATION, OFFICIAL_SHIZUOKA_REMAINEES], "全国の援護制度を磐田の実数の代用にせず、地域資料が示す課題と制度上の支援を二層で示した。住宅所在地・戸数は自治体記録未確認のため断定しない。"),

make("c158", "満蒙開拓と磐田 ── 国策移民・青少年義勇軍・引揚げを一続きに読む", "磐田共通・戦争と植民地史", "108", "磐田地方から満州へ渡った開拓民と青少年義勇軍を、農村振興の成功談でも苦難の引揚げだけでもなく、国策による送出、現地の土地、敗戦、残留、帰国まで一続きの歴史として読む。", [
("『開拓』という言葉を問い直す", ["満蒙開拓は日本政府と関東軍が進めた移民政策で、日本人にとっての入植は、現地住民から見れば土地と生活基盤を奪う植民地政策の一部だった。『未開地を拓いた』という当時の宣伝を事実記述として反復しない。", "静岡県史の目次は、開拓団の組織化、青少年義勇軍の募集、送出、ソ連参戦後の苦難を独立した論点に置く。政策決定と個人の経験を分けて追う構成が必要である。", "地域資料は磐田地方からの参加者を記すが、村別人数、団名、入植地、帰還者数は別資料で照合する。概数を県全体へ広げない。"]),
("なぜ農村から人を送ったか", ["昭和恐慌後の農村経済更生、人口・農地問題、国策宣伝が移民政策と結び付いた。生活の展望を求めた家族の選択と、行政・学校・在郷軍人会による勧奨を同時に見る。", "応募をすべて強制または自発の一語で決めない。募集文書、村会議事録、補助金、学校の進路指導、家族書簡を照合し、選択可能性の幅を具体的に示す。", "土地不足という説明も、農地の所有格差、負債、小作、後継者、職業機会で意味が変わる。<a href=\"/c161.html\">戦後農地改革</a>と比べると、戦前の土地問題への別の国家的回答だったことが見える。"]),
("青少年義勇軍", ["満蒙開拓青少年義勇軍は十代の少年を募集し、国内訓練を経て満州へ送った制度である。教育、勤労、軍事的役割が重なり、単なる農業研修ではなかった。", "学校や教師が勧奨に関与した場合、少年本人の希望だけで進路を説明できない。一方、当時の就職難や大陸への憧れを持った参加者もおり、後知恵で個人を断罪しない。", "隊名や中隊名は同じ姓を持つ指導者名から付く例があり、出身地名とは限らない。磐田出身者の所属を推測で決めず、隊員名簿と軍歴を確認する。"]),
("現地の営農と土地", ["開拓団の営農計画は日本側資料に詳しく残るが、土地の元の耕作者や移転させられた現地住民の記録が少ない。収穫量や施設だけを成果として示さず、土地取得の過程を問う。", "国策資料は衛生、教育、神社、警備を村づくりとして描く。これは日本人入植地の内部制度を知る史料である一方、植民地統治を正当化する目的を持つ。語彙を批判的に読む。", "気候や土壌への適応、物資不足、治安不安は参加者の回想に現れる。記憶の具体性を尊重しつつ、入植地全体を代表するとは限らないと注記する。"]),
("1945年8月と崩壊", ["1945年8月9日のソ連参戦は満州の日本人社会を急速に崩壊させた。静岡県公式資料は戦闘、避難中の飢餓・疾病、多数の犠牲を説明する。", "成人男性の動員で開拓団に女性、子ども、高齢者が多く残った例がある。部隊や行政の保護が十分でなかった経験は、引揚者の証言を通じて検証する。", "自決、襲撃、収容、残留孤児など重い事実を扇情的に描かない。人数は団ごとの名簿で確認し、個人の死に方を伝聞から断定しない。"]),
("引揚げと残留", ["帰国できた人びとは住居と仕事を失い、郷里で生活を再建した。<a href=\"/c157.html\">引揚者住宅</a>は満州史の後日談ではなく、地域社会が戦争責任と生活保障に向き合った場である。", "帰国できず中国に残った人びとへの支援は現在まで続く。静岡県の援護事業は身元引受、年金、交流・語り継ぎを扱い、戦後処理が一世代で終わらないことを示す。", "帰還者を被害者として語る際も、植民地化の中で入植した立場を消さない。加害と被害が同じ人生に重なる歴史を、単純な二分法にしない。"]),
("磐田の実像を確定する手順", ["村別送出名簿、拓務関係文書、学校日誌、在郷軍人会資料、家族書簡、引揚者名簿を年月順に結ぶ。名前の公開は遺族の意向と個人情報を考慮する。", "地域資料の人数が『磐田町』『磐田郡』『現市域』のどれかを確かめる。合併前自治体を現在の市域へ機械的に換算しない。", "現時点で確実なのは国策移民の制度、静岡県からの送出、磐田市公式資料に満蒙開拓団の説明があること。磐田出身者の総数と団別帰還率は未確認である。"])], [("1936", "満州農業移民百万戸計画が国策化。"), ("1938", "満蒙開拓青少年義勇軍の送出が本格化。"), ("1945-08-09", "ソ連参戦で開拓団の避難・崩壊が進む。"), ("1945以後", "引揚げ、残留、生活再建と援護が続く。")], [("c157.html", "引揚者住宅"), ("h004.html", "銃後の生活"), ("r029.html", "竜洋の学童と戦争"), ("c161.html", "農地改革")], ["満蒙開拓", "国策移民", "青少年義勇軍", "引揚げ", "植民地支配"], [OFFICIAL_SHIZUOKA_HISTORY, OFFICIAL_SHIZUOKA_REMAINEES, OFFICIAL_IWATA_PEACE], "送出した日本社会、入植地の現地住民、敗戦後の引揚者・残留者という複数の立場を同時に扱った。磐田の人数は資料の集計範囲が未確認のため断定しない。"),

make("c159", "1918年米騒動と磐田 ── 米価高騰は地域社会へどう届いたか", "磐田共通・近代生活経済史", "110", "1918年の米騒動は富山だけの事件ではない。磐田地方でも米価高騰、買占めへの疑い、生活不安、警察と行政の対応が重なった。全国史と地域資料を照合し、騒動の有無と生活危機を分けて読む。", [
("米騒動の全国的背景", ["第一次世界大戦期の物価上昇、都市人口の増加、米の投機、シベリア出兵方針が米価高騰を深めた。国立国会図書館は1918年7月以降に各地の抗議が広がった経過を示す。", "米価が上がったことと暴動が起きたことは同じではない。安売り要求、集会、示威、商店襲撃、検挙を区別し、地域ごとの出来事を具体的に記す。", "『全国的な米騒動』という大きな語を磐田へ当てはめる前に、新聞、警察記録、町会議事録、米穀商の帳簿を確認する。"]),
("磐田地方の記述", ["地域資料は大正7年8月17日前後、磐田地方でも米価高騰への反発が現れ、警察や行政が対応した趣旨を記す。参加者数や具体的な行動は史料の表現を超えて膨らませない。", "『暴動』『騒擾』『群集』は警察・行政側の分類語で、生活者の目的をそのまま表すとは限らない。取り調べ記録と住民側の請願、新聞記事を比べる。", "事件が起きなかった村でも、米不足や値上がり、外米・代用食、救済販売の影響はあった。騒動史と生活史を分け、両方を記録する。"]),
("米の値段をどう比べるか", ["一升、石、俵など単位が異なるため換算条件を明示する。玄米・白米、等級、小売・卸、日付が違えば価格は比較できない。", "明治・大正の円を現在価値へ一つの数字で換算しない。日雇賃金、世帯収入、米一升の価格という複数の比率で負担感を示す方が実態に近い。", "地域資料にある価格表は『静岡県の百年』からの引用とされる。磐田の店頭価格ではないため、県・全国の趨勢を示す補助資料として位置づける。"]),
("農村でも米を買う人がいた", ["農村だから全世帯が米を自給したとは限らない。小作農、農業労働者、職工、商人、教師、漁民など購入者がおり、収穫前の端境期には農家も買米へ回り得た。", "地主・小作関係では小作料を米で納め、手元の食糧が不足する場合があった。生産地と消費地を単純に分けず、誰が所有し誰が食べたかを見る。", "磐田の工場労働者や町場住民にとって、米価は賃金の実質価値を左右した。<a href=\"/c075.html\">遠州織物の労働史</a>と家計をつなぐ必要がある。"]),
("行政と警察の対応", ["政府は国費による米価対策、輸入、取締りを進め、地域では廉売、寄付、救済、警備が行われた。磐田でどの措置が実施されたかは町村予算と新聞で確かめる。", "警察の秩序維持と行政の生活救済は同時に動いた可能性がある。検挙件数だけで政策効果を測らず、価格が下がったか、困窮世帯へ届いたかを見る。", "商人を一律に買占め犯とみなさない。在庫、仕入れ、販売制限、組合指示を確認し、噂と確認された行為を分ける。"]),
("女性の行動を見落とさない", ["全国史では米を日々買う女性たちの行動が米騒動の端緒として重視される。一方、警察・新聞記録は男性代表者を中心に書く傾向がある。", "磐田の参加者構成は未確認であり、『主婦が先導した』と全国像をそのまま移さない。女性の日記、婦人会資料、裁判記録があれば補う。", "家計管理、炊事、食糧確保を政治ではない日常として扱うと、価格抗議の主体が消える。生活維持の交渉も地域政治の一部として読む。"]),
("騒動後の意味", ["米騒動は寺内内閣退陣や原敬内閣成立の背景となったが、磐田の一出来事が直接政権を変えたとは書けない。全国的連鎖の中で地域の抗議を位置づける。", "米穀政策、社会事業、労働運動の変化へ影響したという通説を、地域の制度開始年と照合する。後の救護法や職業紹介へ単線的につながったと決めない。", "確実なのは全国的米価高騰と米騒動、地域資料が磐田地方の動揺を記すこと。具体的参加者数、逮捕、被害店舗は追加の一次資料が見つかるまで未確認とする。"])], [("1914", "第一次世界大戦開始。物価上昇が進む。"), ("1918-07", "シベリア出兵方針と米価高騰。"), ("1918-08", "米騒動が全国へ拡大。"), ("1918以後", "米穀・社会政策の見直しが進む。")], [("c160.html", "救護法から生活保護へ"), ("c144.html", "不景気と匡救事業"), ("c075.html", "遠州織物と女性労働"), ("c163.html", "新円切替")], ["米騒動", "米価", "1918年", "生活経済", "社会運動"], [OFFICIAL_NDL_RIOT], "全国史で確認できる原因と地域資料の出来事を分離し、磐田の参加者数・被害・検挙を未確認とした。価格表は県の趨勢であり磐田店頭価格ではないと明示する。"),

make("c160", "救護法から生活保護へ ── 磐田の困窮者支援と生存権", "磐田共通・社会福祉史", "116〜117", "昭和恐慌下の救護法は、困窮者支援を市町村の行政実務に組み込んだ。戦後の生活保護法までをたどり、慈善、救貧、権利保障の違いと、地域の支援が届かなかった人びとを検証する。", [
("救護法が対象とした人びと", ["救護法は1929年に公布され1932年に施行された。高齢、幼弱、疾病、障害などにより生活できない人を対象としたが、普遍的な最低生活保障ではなかった。", "地域資料は昭和初期の不況下で救護対象が増え、町村が生活費や医療扶助などを扱ったことを記す。対象人数は年度と旧町村の範囲を確認して読む。", "『救護を受けた』ことを本人の失敗として書かない。失業、病気、家族構成、低賃金、農村不況という社会条件を先に置く。"]),
("市町村と方面委員", ["救護事務は市町村長の責任だけで完結せず、方面委員が生活状況の把握や相談に関わった。厚生労働省資料は、方面委員が救護法上、市町村長を補助する委員に位置づけられたと説明する。", "方面委員は後の民生委員へつながるが、名称変更だけで制度が同じとは言えない。選任、権限、守秘、対象者の権利を各時期で比較する。", "近隣の人物が調査する仕組みは支援への入口となる一方、プライバシーや選別の問題を伴う。善意だけで制度を評価しない。"]),
("救護を受ける条件", ["戦前の救貧制度には扶養義務者の有無、勤労能力、素行などの選別が強く働いた。申請できても認定されない人、申請自体をためらう人がいた可能性がある。", "地域資料の給付額を読む際は、生活費、医療、埋葬、施設収容を分ける。一人当たり額を世帯給付へ置き換えず、現金と現物を区別する。", "受給者名簿は重要な史料だが、個人名を公開する必要はない。統計化し、差別を再生産しない形で家族構成や支援経路を分析する。"]),
("戦後の旧生活保護法", ["敗戦直後は引揚者、失業者、戦災者、孤児、傷病者への緊急援護が必要になり、1946年に旧生活保護法が施行された。救護法などは旧法へ統合された。", "旧法は戦前の慈恵的救貧から前進したが、厚生省自身が1950年通達で不備を認め、新憲法の生存権を明確にする再編を説明した。制度評価を当時の公文書で確認できる。", "磐田の救護件数と戦後保護件数を単純に増減比較しない。対象、基準、統計単位、貨幣価値、人口が異なる。"]),
("1950年生活保護法", ["現行生活保護法は1950年に公布・施行され、国が最低生活を保障し自立を助長する立場を明確にした。不服申立てを含む法的地位の確立は、救貧から権利保障への重要な変化である。", "しかし法律が変われば偏見や窓口運用が直ちに消えるわけではない。申請、調査、決定、扶助、相談の記録から地域実務を検証する。", "<a href=\"/c157.html\">引揚者援護</a>や戦没者遺族援護は生活保護と別制度を持つ。複数制度が重なる世帯で、どの制度が優先されたかを見る。"]),
("女性・子ども・高齢者", ["世帯主中心の行政記録では、無償の介護、ひとり親、孤児、家内労働が見えにくい。対象者の属性を分類するときも、当時の家族観をそのまま正当化しない。", "救護法下の養老院、孤児支援、医療扶助は現在の高齢者福祉・児童福祉・医療保障と同じ制度ではない。後の制度名で遡及的に呼ばない。", "子どもの就学、栄養、医療を家族の困窮だけに帰さず、学校・保健・社会事業の連携として調べる。<a href=\"/c150.html\">貧困児童支援</a>と接続する。"]),
("地域の数字を読む", ["被救護人員は月間実数、延べ人数、年度末現在で値が変わる。人口比を出す場合は同じ年・区域の人口を使い、合併後市域へ換算しない。", "支出額も国庫・県・町村負担、現物、施設費で区分する。決算額だけで需要を測ると、申請を断念した人が統計から消える。", "本稿で確実なのは制度年、地域資料が昭和初期の救護実務を記すこと、厚生省が1950年に権利保障への再編を明示したこと。磐田の受給率は追加統計が必要である。"])], [("1929", "救護法公布。"), ("1932", "救護法施行。"), ("1946", "旧生活保護法施行。"), ("1950", "現行生活保護法公布・施行。")], [("c159.html", "1918年米騒動"), ("c144.html", "不景気と匡救事業"), ("c150.html", "貧困児童支援"), ("c157.html", "引揚者住宅")], ["救護法", "方面委員", "生活保護法", "生存権", "社会福祉"], [OFFICIAL_MHLW_WELFARE], "救護法と生活保護法を連続した名称変更とはせず、対象選別を伴う救貧と憲法25条下の権利保障の制度差を中心に据えた。個人名は扱わない。"),

make("c161", "磐田の農地改革 ── 小作地から自作地へ、村の権力はどう変わったか", "磐田共通・戦後農業史", "128〜131", "戦後農地改革は、地主の土地を国が買収し小作農へ売り渡した制度変更だった。磐田地方の自作・小作比率、農地委員会、価格、地域差を全国制度と照合し、単純な成功物語にしない。", [
("改革前の地主と小作", ["戦前の農村では、自作地だけを耕す農家、自作と小作を併せる農家、小作地中心の農家が併存した。地主も大地主から小規模貸付まで幅があり、二者を固定した階級像だけで地域を説明できない。", "小作料は米納と金納、田と畑、豊凶で条件が異なる。地域資料が示す小作料率を全国平均と比較する際は、収穫量に対する割合か地代額かをそろえる。", "農地所有と村役・金融・水利が結び付く場合、改革は土地だけでなく地域政治の力関係を変えた可能性がある。議会・農会・産業組合の役員名簿と重ねる。"]),
("改革の法制度", ["農林水産省資料は1946年の自作農創設特別措置法などにより、一定規模以上の小作地を国が買収し、小作人へ売り渡したと説明する。", "全国では約193万町歩が開放され、自作農戸数は172.9万戸から382.2万戸へ、小作割合は46％から10％へ低下したとされる。これは全国値であり磐田の数字ではない。", "第一次改革と第二次改革、在村・不在村地主、保有限度の違いを区別する。『GHQが土地を配った』という一文で制度を終わらせない。"]),
("磐田の農地委員会", ["改革実務は市町村農地委員会が土地、所有者、耕作者、買収・売渡しを確認した。委員選挙と構成は、誰が地域の土地情報を握り、紛争を調整したかを示す。", "地域資料は磐田地方で農地改革が進み、多くの小作地が自作地へ移ったとする。買収面積と対象農家数は旧町村別台帳で再計算すべきである。", "委員会の議決が全員一致とは限らない。異議申立て、境界、水利、宅地・山林の扱いを議事録から拾い、成立した売渡しだけでなく争いも記録する。"]),
("価格とインフレ", ["買収・売渡価格は法定価格で決まり、戦後インフレの中で実質価値が急減した。地主側の損失感と小作側の取得負担を同じ価格表から別々に読む。", "<a href=\"/c163.html\">新円切替</a>や預金封鎖と重なるため、額面だけでは負担を判断できない。支払方法、国債、償還、物価指数を確認する。", "改革を不当な収奪か完全な解放の一方に固定せず、制度目的、補償、生活への効果、地域政治の変化を別項目で評価する。"]),
("水利と小作地", ["所有権が移っても用水路、ため池、排水、農道は共同管理が必要だった。<a href=\"/n089.html\">大池事件</a>が示すように、水利権は土地所有だけでは解決しない。", "耕作者が所有者になれば改良投資の意欲が高まったという通説があるが、用水費、資材、機械、労働力がなければ効果は限定される。", "土地台帳と水利組合名簿を重ね、所有移転後に賦課と議決権がどう変わったかを確認する。農地改革を筆の移動だけで終わらせない。"]),
("女性と世帯名義", ["農地売渡しは世帯主名義に集中しやすく、女性が耕作を担っていても所有者名簿へ現れにくい。戦争未亡人や女性世帯主の扱いを個別に調べる。", "家族労働を一単位とみなす農家統計は、誰が意思決定し収益を管理したかを示さない。聞き取り、相続、農協女性部資料で補う。", "男女平等という戦後原則が農地所有にどこまで及んだかは、名義の男女比と相続経過を見なければ断定できない。"]),
("改革後の課題", ["自作農が増えても経営面積が小さければ所得は安定しない。高度成長期には兼業化、離農、農地転用が進み、改革で生まれた小規模自作農構造が別の課題になった。", "農林水産省資料は1952年農地法が改革成果の維持を目的としたと説明する。後の規模拡大政策とは目的が異なり、一つの直線的政策として扱わない。", "確実なのは全国制度と地域資料が改革実施を記すこと。磐田の開放率、地主・小作戸数、女性名義比率は旧町村台帳の再集計が必要である。"])], [("1945", "第一次農地改革が始まる。"), ("1946", "自作農創設特別措置法などを制定。"), ("1947〜1950", "買収・売渡しが地域で進む。"), ("1952", "農地法が改革成果の維持を制度化。")], [("c162.html", "産業組合から農協へ"), ("c163.html", "新円切替"), ("n089.html", "大池事件"), ("c158.html", "満蒙開拓")], ["農地改革", "自作農", "小作農", "農地委員会", "戦後農業"], [OFFICIAL_MAFF_REFORM], "全国の開放面積・自作農戸数を磐田の実績と誤認させず比較値として置いた。地域の開放率は未確認とし、土地・水利・家族名義を分けた。"),

make("c162", "産業組合から農協へ ── 磐田の共同購入・信用・営農指導", "磐田共通・協同組合史", "130〜133", "磐田地方の産業組合と農会は、戦後の農業協同組合へそのまま改名されたわけではない。共同購入、販売、信用、技術指導の機能を分け、制度の断絶と人・施設の継承を検証する。", [
("三つの組織を分ける", ["戦前の産業組合は信用、購買、販売、利用などの共同事業を担い、農会は農業技術の指導や行政的事業を担った。戦後の農業協同組合は1947年農協法に基づく別制度である。", "地域資料は『農会から農協へ』と簡潔に表すが、組織、法的根拠、会員、資産、職員の移行を一つずつ確認しなければ単純な改称とは言えない。", "<a href=\"/c118.html\">報徳運動</a>の共同・積立思想が地域の協同組織を受け入れる土壌になった可能性はあるが、思想的影響は規約や役員資料で裏付ける。"]),
("産業組合の事業", ["農家が肥料、種子、農具、生活物資を共同購入すれば取引条件を改善できる。農産物の共同販売は品質、数量、価格交渉を組織化した。", "信用事業は農家の資金需要を支える一方、貸付審査、保証、延滞、役員兼職によって地域内の力関係を生む。成功例だけでなく損失・整理記録も見る。", "組合員外の小作人、農業労働者、女性がどこまで利用できたかを確認する。『農村全体の組織』という表現で排除を隠さない。"]),
("農会と技術員", ["地域資料は大正期以降、町村農会が農業技術員を置き、稲作、病害虫、防除、肥料、品種を指導したと記す。技術普及は収量向上を目指す行政と地域の接点だった。", "技術員の推奨が直ちに全農家へ採用されたとは限らない。費用、労働、土地条件、経験知との衝突があり、試験田・講習会・普及率を確かめる。", "農会の資料は成果を強調しやすい。反収の増加を天候や品種だけに帰さず、水利、肥料、労働、統計方法を合わせて検討する。"]),
("戦時統制で変わる組合", ["戦時期、肥料・米・生活物資の統制が強まり、共同組織は自主的な協同だけでなく供出・配給を実施する行政末端の役割を担った。", "同じ組合施設と職員が使われても、組合員の利益と国家統制の目的は一致しない場合がある。議決による事業と上からの割当を区別する。", "<a href=\"/h004.html\">銃後の生活</a>に供出と配給を加えると、農村組織が戦争動員へ組み込まれた過程が見える。"]),
("1947年農協法", ["農林水産省の政策年表は1947年に農業協同組合法を置く。戦後民主化と農地改革の中で、農業者の自主的協同組織として農協を再編する制度だった。", "ただし設立総会が法施行直後に開かれたか、旧組織の資産・負債をどう処理したかは地域ごとに異なる。設立認可、定款、出資、役員選挙を確認する。", "農協の成立を国の命令か住民の自発の一方に決めない。法制度、行政指導、旧組織の実務、人びとの必要が重なった。"]),
("磐田地方の再編", ["地域資料は各町村の農業会・農会が解散・再編され、農協が成立した経過を記す。後の合併農協と現在のJA区域を遡って同じ組織として扱わない。", "旧町村単位の組合名、設立日、組合員数、出資金、事務所を表にすれば、行政区域と経済圏の一致・不一致が見える。", "役員名簿の継続は人的連続を示すが、制度理念の連続を自動的に証明しない。旧地主、改革後自作農、技術員、女性の参加を比較する。"]),
("信用と共済の広がり", ["農協は購買・販売だけでなく信用、共済、営農指導を一体的に扱うようになった。複数事業の利益・リスクを分けて決算を読む。", "農家にとって一つの窓口は便利だが、選択肢が少ない地域では組合との関係が生活全体を左右する。利用率、手数料、配当、脱退規定を確認する。", "確実なのは制度上の移行と地域資料の組織化記述である。磐田各農協の設立日、初期役員、資産承継は個別定款・決算が未確認で、今後の調査課題とする。"])], [("1900", "産業組合法制定。"), ("戦前", "産業組合・農会が購買、信用、技術指導を担う。"), ("1943", "農業団体の戦時再編が進む。"), ("1947", "農業協同組合法制定。"), ("戦後", "旧町村ごとの農協成立と後の広域合併。")], [("c161.html", "磐田の農地改革"), ("c118.html", "遠州報徳運動"), ("h004.html", "銃後の生活"), ("s023.html", "南部農業の歩み")], ["産業組合", "農会", "農業協同組合", "営農指導", "協同組合"], [OFFICIAL_MAFF_REFORM, OFFICIAL_MAFF_LAND], "産業組合・農会・農業会・農協を同一組織とせず、法制度と機能を分解した。磐田各組合の資産承継は未確認として、設立資料を今後の課題にした。"),

make("c163", "新円切替と磐田 ── 預金封鎖は暮らしと地域金融をどう変えたか", "磐田共通・戦後金融史", "136〜139", "1946年の新円切替は、紙幣のデザイン変更ではなく、旧紙幣の強制預入と預金封鎖を伴うインフレ対策だった。磐田の銀行・郵便局・家計に起きた混乱を日本銀行資料と地域記録で検証する。", [
("何が切り替わったのか", ["日本銀行は1946年2月、5円以上の旧銀行券を金融機関へ強制預入させ、既存預金とともに封鎖し、生活費・事業費に限って新銀行券で払い出す措置を新円切替と説明する。", "単なる旧札と新札の交換ではない。通貨量を抑え、インフレを止めるため、現金保有と預金利用を同時に制限した非常措置だった。", "証紙を貼った旧券が暫定的に新円として使われたため、紙幣画像だけで時期を判定しない。証紙、券種、使用期限を確認する。"]),
("発表から実施まで", ["措置は短期間で告知・実施され、家庭と事業者は現金の預入を急いだ。地域資料は銀行・郵便局に人が集まり、窓口が混乱した趣旨を記す。", "行列の長さ、預入額、窓口数は写真や業務日誌がなければ断定できない。全国の映像を磐田の光景として代用しない。", "銀行だけでなく郵便貯金、農業会・信用組合、企業給与の対応を調べる。どの機関がどの地域を担当したかでアクセス格差が生じた可能性がある。"]),
("預金封鎖と生活費", ["封鎖預金からの払出しには生活費上限が設けられた。世帯人数、給与支払、医療、冠婚葬祭などで必要額が違い、一律制限の影響も異なった。", "現金収入が少ない農家でも、肥料・種子・税・小作料の支払時期には資金が必要になる。現金経済と自給の比率を家計簿から確認する。", "預金を持たない低所得層は封鎖される資産が少ない一方、物価高の打撃を直接受けた。資産家だけの問題として扱わない。"]),
("商店と企業の資金繰り", ["商店は仕入れ代金、工場は賃金と原料費を払う必要があり、事業費払出しの認定が営業継続を左右した。許可申請と実際の払出しを区別する。", "地域資料にある商店の混乱を、すべて倒産へ結び付けない。在庫、掛売り、物々交換、代用決済でしのいだ例も考えられる。", "<a href=\"/c075.html\">遠州織物</a>では糸・染料・賃金の支払が必要だった。産業ごとの運転資金構造を比べると影響の違いが見える。"]),
("農地改革との同時進行", ["新円切替は<a href=\"/c161.html\">農地改革</a>の買収・売渡価格、地主補償、農家負債の実質価値にも関係する。額面が同じでもインフレで購買力は変わった。", "地主の受け取った補償が実質的に目減りしたという評価は、支払時期、国債、物価を確認して行う。農地改革の是非を新円切替だけで説明しない。", "負債の実質負担も借入条件と返済時期で異なる。『借金が帳消しになった』という伝承は契約・利率・返済記録で確かめる。"]),
("政策は成功したのか", ["新円切替は通貨を吸収したが、財政・供給不足などインフレ要因が残り、物価上昇はすぐには収まらなかった。政策の目的と結果を分ける。", "後のドッジ・ラインまで含めて戦後安定化を説明する場合、1946年と1949年の政策を混同しない。<a href=\"/c144.html\">二つの緊縮期</a>で時間差を確認する。", "個人の損得だけで政策を評価せず、物価、賃金、生産、預金、闇市場への影響を複数指標で見る。"]),
("地域金融史料を探す", ["銀行支店日誌、郵便局業務報告、農業会決算、商工会議事録、家計簿、新聞広告を同じ週ごとに並べる。告知と現場対応のずれが分かる。", "預入額を公開する場合は個人名を伏せ、階層別集計にする。旧紙幣や通帳の画像には所有者情報が残るため、利用許諾とマスキングが必要である。", "確実なのは日本銀行が示す制度内容と地域資料が混乱を記すこと。磐田の預入総額、封鎖預金残高、窓口別人数は未確認である。"])], [("1945", "敗戦後、物価上昇が加速。"), ("1946-02-16", "金融緊急措置令などを公布。"), ("1946-03", "旧券の預入と新円での制限払出し。"), ("1946-10", "証紙貼付券の暫定利用が終了。"), ("1949", "ドッジ・ラインによる別の緊縮政策。")], [("c144.html", "不景気とドッジ・ライン"), ("c161.html", "磐田の農地改革"), ("c159.html", "1918年米騒動"), ("c075.html", "遠州織物")], ["新円切替", "預金封鎖", "戦後インフレ", "地域金融", "日本銀行券"], [OFFICIAL_BOJ], "日本銀行の制度説明を基準にし、地域資料の窓口混乱を磐田の預入総額へ拡張しない。証紙貼付券と新券を区別し、政策目的と効果を分けた。"),

make("c164", "職業紹介と戦後雇用 ── 磐田で仕事を探す仕組みの成立", "磐田共通・労働行政史", "144〜147", "職業紹介所は求人と求職を結ぶ窓口であると同時に、失業、引揚げ、復員、女性就労、産業転換を映す場所だった。磐田の職業紹介から公共職業安定所への変化を、法制度と地域経済の両側から読む。", [
("職業紹介とは何か", ["職業安定法は職業紹介を、求人と求職の申込みを受け、雇用関係の成立をあっせんすることと定義する。単なる求人掲示ではなく、条件確認と仲介を伴う行政実務である。", "戦前の職業紹介所、戦時の労務動員、戦後の公共職業安定所は目的と法的環境が異なる。同じ窓口の連続だけで制度を説明しない。", "地域資料は中泉町の職業紹介所、改称・移転、戦後の労働行政を記す。所在地と所管は各年の官報・電話帳・行政文書で再確認する。"]),
("戦前の口入れから公営紹介へ", ["職業紹介が公営化される以前、仕事の仲介には口入れ業者、親方、縁故、学校、村役人が関わった。手数料や拘束、情報格差が労働者の選択を狭める場合があった。", "公営紹介所は無料・公平な仲介を掲げたが、職種、性別、年齢、出身地による求人側の選別が消えたわけではない。求人票と紹介結果を比較する。", "農繁期の季節労働、工場、商店、家事使用人、製茶・織物など、磐田の産業構成に応じた求人があったはずだが、具体的構成は統計確認が必要である。"]),
("戦時労務動員との断絶", ["戦時期の職業行政は労働力の国家配置と結び付き、勤労動員や転職制限が強まった。自由な職業選択を仲介する仕組みとは異なる。", "同じ職員・台帳・建物が戦後へ継承されても、目的は転換した。制度断絶と人的・物的連続を分けて記す。", "学徒動員、女子挺身隊、軍需工場配置を通常の就職実績へ入れない。<a href=\"/h003.html\">学徒動員</a>の強制性を明記する。"]),
("1947年職業安定法", ["1947年の職業安定法は、公共に奉仕する職業安定機関、職業選択の自由、均等待遇を原則に置いた。敗戦後の労働行政を権利の側から再編した法律である。", "法文の原則と窓口実務が一致したかは別問題である。求人の性別指定、身元調査、年齢制限、住込条件などを求人票から検証する。", "『公共職業安定所』への改称年と中泉の組織変遷は、全国法施行日だけで決めず地域沿革を優先する。"]),
("引揚者・復員者と仕事", ["敗戦後は復員者、引揚者、軍需工場離職者が同時に仕事を求めた。住居、食糧配給、戸籍、職業紹介が連動し、窓口間の紹介が重要だった。", "<a href=\"/c157.html\">引揚者住宅</a>と就職を合わせて見れば、定着支援の成否が分かる。紹介件数だけでなく就職後の継続、賃金、住居を追う。", "軍歴や外地経験が技能として評価された場合と、資格を証明できず不利になった場合がある。職種別の個別記録なしに一般化しない。"]),
("女性と若者の就職", ["戦後、軍需動員から解放された女性が家庭へ戻る圧力と、生活のため働く必要が併存した。紹介統計を男女別に見ると、職種分離と賃金差が見える。", "学校卒業者の職業紹介は学校と安定所が分担した。進学率が上がる以前、若者の地域内外移動を求人先と通勤手段から追う。", "家事使用人や内職は統計に現れにくい。女性の就労を工場雇用だけで数えず、家内工業と農業労働を含める。"]),
("高度成長と求人不足の反転", ["戦後直後の失業から高度成長期の人手不足へ、職業安定所の課題は変わった。企業誘致、道路、鉄道、住宅が労働市場を広げた。", "<a href=\"/u053.html\">東部台地工場群</a>の立地は雇用を生んだが、農家の兼業化、通勤、若年流出とも関係した。就職者数だけで地域への効果を測らない。", "地域資料が『経済成長』を明るく描く箇所も、公害、交通、長時間労働、農地転用を併記して評価する。"]),
("統計の読み方", ["求人数、求職者数、紹介件数、就職件数は異なる。求人倍率を出すには同じ期間・地域・常用区分をそろえ、延べ件数と実人数を分ける。", "職安統計に現れない縁故就職、自営、家族従業、日雇いがある。窓口利用率を地域の全就業移動とみなさない。", "確実なのは地域資料が職業紹介所の存在を記し、1947年法が自由・均等・公共奉仕を原則にしたこと。磐田の職種別紹介実績は年報未確認である。"])], [("戦前", "公営職業紹介所が求人・求職を仲介。"), ("戦時期", "労務統制と動員が強まる。"), ("1947-11-30", "職業安定法公布。"), ("戦後", "公共職業安定所が復員・引揚げ・失業へ対応。"), ("高度成長期", "人手不足と広域通勤へ課題が変化。")], [("c157.html", "引揚者住宅"), ("h003.html", "学徒動員"), ("u053.html", "東部台地工場群"), ("c144.html", "不景気とドッジ・ライン")], ["職業紹介所", "公共職業安定所", "職業安定法", "戦後雇用", "労働市場"], [OFFICIAL_MHLW_JOB], "法文上の職業選択の自由と、地域の窓口実務・戦時労務統制を区別した。地域の求人構成は未確認で、全国傾向を磐田の統計として扱わない。"),
]
